/// Render a month-end statement: every invoice (via [`render_invoice`]),
/// separated by a blank line, followed by a final `NEXT #<n>` line naming the
/// number the next issued invoice will receive.
///
/// This is read-only: it only *peeks* at [`NEXT_INVOICE`] and never calls
/// [`issue_number`], so rendering a statement consumes no invoice numbers.
pub fn render_invoice_statement(invoices: &[Invoice]) -> String {
    let next = NEXT_INVOICE.load(Ordering::SeqCst);
    let mut sections: Vec<String> = invoices.iter().map(render_invoice).collect();
    sections.push(format!("NEXT #{next}\n"));
    sections.join("\n")
}

